<?php
require_once dirname(__DIR__).'/config/database.php';require_once dirname(__DIR__).'/includes/layout.php';require_login('admin');$status=$_GET['status']??'';$allowed=['pending','success','failed'];$sql='SELECT p.*,u.full_name,u.email,c.title FROM payments p JOIN users u ON u.id=p.user_id JOIN courses c ON c.id=p.course_id';$params=[];if(in_array($status,$allowed,true)){$sql.=' WHERE p.status=?';$params[]=$status;}$sql.=' ORDER BY p.created_at DESC';$q=$pdo->prepare($sql);$q->execute($params);$payments=$q->fetchAll();start_page('Payment transactions','payments'); ?>
<div class="mb-4 flex flex-wrap items-center justify-between gap-3"><p class="muted">Provider-verified records for five-shilling course enrollments.</p><form><select class="field !w-44" name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach($allowed as $s): ?><option value="<?= e($s) ?>" <?= $status===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></form></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Course</th><th>Provider</th><th>School reference</th><th>Provider receipt / reference</th><th>Amount</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td class="font-semibold"><?= e($p['full_name']) ?><div class="text-xs text-slate-400"><?= e($p['email']) ?></div></td><td><?= e($p['title']) ?></td><td><?= e(strtoupper($p['provider'])) ?></td><td class="font-mono text-xs"><?= e($p['reference']) ?></td><td class="font-mono text-xs"><?= e($p['provider_transaction']?:$p['provider_reference']?:'—') ?></td><td>KSh <?= number_format((float)$p['amount_kes'],2) ?></td><td><span class="badge badge-<?= e($p['status']==='success'?'success':($p['status']==='failed'?'failed':'pending')) ?>"><?= e($p['status']) ?></span><?php if($p['failure_reason']): ?><div class="text-xs text-rose-700" title="<?= e($p['failure_reason']) ?>">See reason</div><?php endif ?></td><td><?= e(date('M j, Y H:i',strtotime($p['created_at']))) ?></td></tr><?php endforeach ?><?php if(!$payments): ?><tr><td colspan="8" class="py-8 text-center text-slate-500">No payment records match this filter.</td></tr><?php endif ?></tbody></table></div><?php end_page(); ?>
